import * as React from "react";
import "./MenuBlock.scss";
import NormalTextLink from "../normalTextLink/NormalTextLink";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";

export interface MenuBlockProps {
  /**
   * Unique identifier for the menu block
   */
  id?:string;
  
   /**
   * Array of menu items to be rendered.
   */
  menuItems: {
    label?: string;
    link?: string;
    leadingIcon?: keyof typeof SvgMpaIcon | any;
    showDivider?: boolean;
    disabled?: boolean;
    subMenuItems?: MenuBlockProps["menuItems"];
    LinkComponent?: React.ComponentType<any>;
  }[];
  
  /**
   * Optional colour scheme for the menu block.
   */

  colour?: "primary" | "secondary" | "tertiary";

  /**
   * Callback triggered when a menu item is clicked.
   */
  onItemClick?: (item: any, index: number, parentIndex: number | null) => void;
}

const MenuBlock: React.FC<MenuBlockProps> = ({ id, menuItems = [], colour, onItemClick  }) => {
  // Store open index as a string, starting from the top level
  const [openItemIndex, setOpenItemIndex] = React.useState<(number | null)[]>([]);

  // Handle item click (accordion behavior)
  const handleSelectItem = (
    item: MenuBlockProps["menuItems"][number],
    index: number, 
    //parentIndex: number | null = null
    level: number
  ) => {
    const newOpenItemIndex = [...openItemIndex];

    //const level = parentIndex === null ? 0 : parentIndex + 1;

    if (newOpenItemIndex.length <= level) {
      newOpenItemIndex.push(null);
    }

    // Toggle the open state for the current level
    if (newOpenItemIndex[level] === index) {
      newOpenItemIndex[level] = null; // Close the current item if it's already open
    } else {
      newOpenItemIndex[level] = index; // Open the current item
    }

    newOpenItemIndex.splice(level + 1);

    setOpenItemIndex(newOpenItemIndex);

    // Call the external click handler if passed
    if (typeof onItemClick === "function") {
      onItemClick(item, index, level);
    }
    // if (typeof onItemClick === "function") {
    //   onItemClick(item, index, parentIndex);
    // }
  };

  const menuClassName = `sgds menu-item ${colour} `;
  const mainMenuClassName = `menu-block`;


  // Recursive function to render menu items and handle submenus
  const renderMenuItems = (
    menuItems: MenuBlockProps["menuItems"],
    //parentIndex: number | null
    level: number
  ) => {
    return menuItems.map((item, index) => {    

      //const level = parentIndex === null ? 0 : parentIndex + 1;

      // Determine if this item is open based on the parent index and the current open state
      const isOpen = openItemIndex[level] === index;
      return (
        <li
          key={index}
          className={`menu-item ${menuClassName} ${isOpen ? "selected" : "default"} 
          ${item.showDivider ? "showDivider" : ""} ${item?.disabled ? "disabled" : ""}`}
        >
          <div className="menu-list-item" onClick={(e) => {e.stopPropagation(); handleSelectItem(item,index, level)}}>
            {item?.leadingIcon && 
              <span className="sub-menu-icon"> 
              {typeof item.leadingIcon === "string" && item.leadingIcon in SvgMpaIcon ? (
                <MpaIcon iconName={item.leadingIcon } />
              ) : (
                item.leadingIcon
              )}
            </span>}
            { item.LinkComponent ? 
                <item.LinkComponent to={item.link}>
                  <NormalTextLink id={String(index)}>{item.label}</NormalTextLink>
                </item.LinkComponent> : 
                <NormalTextLink id={String(index)} href={item?.link}>{item.label}</NormalTextLink>
            }
                       
            {item.subMenuItems && item.subMenuItems.length > 0 && (
              <span className="sub-menu-arrow">
                  <MpaIcon iconName={'ChevronRight'}/>
              </span>
            )}
            
            {/* Render submenus if they exist */}
            {item.subMenuItems && item.subMenuItems.length > 0 && isOpen && (
              <ul className={`submenu ${mainMenuClassName} ${isOpen ? "selected" : "default"}   `}>
                 {renderMenuItems(item.subMenuItems, level + 1)}  
              </ul>
            )}
          </div>
        </li>
      );
    });
  };

  return (
      <ul id={id} className={`menu ${mainMenuClassName}`}>{renderMenuItems(menuItems, 0)}</ul>
  );

};

export default MenuBlock;
